<template>
  <form @submit="formSubmit">
    <div class="offcanvas offcanvas-end" tabindex="-1" id="form-offcanvas" aria-labelledby="form-offcanvasLabel">
      <div class="offcanvas-header">
        <h5 class="offcanvas-title" id="form-offcanvasLabel">
          <template v-if="currentId != 0">
            <span v-if="parent_id !== null">{{ editNestedTitle }}</span> <span v-else>{{ editTitle }}</span>
          </template>
          <template v-else>
            <span v-if="parent_id !== null">{{ createNestedTitle }}</span> <span v-else>{{ createTitle }}</span>
          </template>
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
      </div>
      <div class="offcanvas-body">
        <div class="row">
          <div class="col-12">
            <div class="form-group">
              <div class="text-center">
                <img :src="ImageViewer || defaultImage" alt="feature-image" class="img-fluid mb-2 avatar-140 avatar-rounded" />
                <div class="d-flex align-items-center justify-content-center gap-2">
                  <input type="file" ref="profileInputRef" class="form-control d-none" id="file_url" name="file_url" @change="fileUpload" accept=".jpeg, .jpg, .png, .gif" />
                  <label class="btn btn-info" for="file_url">{{ $t('messages.upload') }}</label>
                  <input type="button" class="btn btn-danger" name="remove" :value="$t('messages.remove')" @click="removeLogo()" v-if="ImageViewer" />
                </div>
              </div>
            </div>
            <InputField :is-required="true" :label="$t('category.lbl_name')" placeholder="" v-model="name" :error-message="errors.name" :error-messages="errorMessages['name']"></InputField>
            <div v-for="field in customefield" :key="field.id">
              <FormElement v-model="custom_fields_data" :name="field.name" :label="field.label" :type="field.type" :required="field.required" :options="field.value" :field_id="field.id"></FormElement>
            </div>
            <div class="form-group col-md-12">
              <label class="form-label" for="description">{{ $t('category.lbl_description') }} <span class="text-danger">*</span></label>
              <textarea :is-required="true" class="form-control" v-model="description" id="description"></textarea>
              <span v-if="errorMessages['description']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['description']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.description }}</span>
            </div>
            <div class="form-group col-md-12">
              <div class="form-group">
                <label class="form-label" for="yogacenter">{{ $t('yoga.lbl_yoga_center') }} <span class="text-danger">*</span></label>
                <Multiselect id="yogacenter_id" v-model="yogacenter_id" :multiple="true" :value="yogacenter_id" :placeholder="$t('yoga.lbl_yoga_center')" v-bind="multiSelectOption" :options="yogacenter.options" class="form-group"> </Multiselect>
                <span v-if="errorMessages['yogacenter_id']">
                  <ul class="text-danger">
                    <li v-for="err in errorMessages['yogacenter_id']" :key="err">{{ err }}</li>
                  </ul>
                </span>
                <span class="text-danger">{{ errors.yogacenter_id }}</span>
              </div>
            </div>
            <div class="form-group">
              <label class="form-label" for="yogacategory">{{ $t('yoga.lbl_yoga_category') }} <span class="text-danger">*</span></label>
              <Multiselect id="category_id" v-model="category_id" :value="category_id" :placeholder="$t('yoga.yogacategory')" v-bind="singleSelectOption" :options="yogacategory.options" class="form-group"> </Multiselect>
              <span v-if="errorMessages['category_id']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['category_id']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.category_id }}</span>
            </div>
            <InputField class="" type="number" :is-required="true" :label="`${$t('yoga.lbl_charges')} (${CURRENCY_SYMBOL})`" placeholder="" v-model="charges" :error-message="errors['charges']" :error-messages="errorMessages['charges']"></InputField>
            <InputField class="" type="capacity" :is-required="true" :label="`${$t('yoga.lbl_capacity')}`" placeholder="" v-model="capacity" :error-message="errors['capacity']" :error-messages="errorMessages['capacity']"></InputField>
            <InputField class="min-datetimepicker-time" type="text" :is-required="true" :label="$t('yoga.lbl_duration_min')" placeholder="" v-model="duration" :error-message="errors['duration']" :error-messages="errorMessages['duration']"></InputField>
            <div class="form-group">
              <label class="form-label" for="extra">{{ $t('yoga.extra') }}</label>
              <div class="multi-field-wrapper">
                <div class="multi-fields">
                  <div class="multi-field" v-for="(field, index) in extra" :key="index">
                    <div class="input-group mb-3">
                      <input type="text" v-model="field.name" class="form-control" :placeholder="$t('yoga.name')" />
                      <input type="text" v-model="field.value" class="form-control" :placeholder="$t('yoga.value')" />
                      <button type="button" class="btn btn-danger remove-field" @click="removeField(index)" v-show="extra.length > 1">Remove</button>
                    </div>
                  </div>
                </div>
                <button type="button" class="btn btn-primary add-field" @click="addField">Add field</button>
              </div>
            </div>

            <div class="form-group">
              <div class="d-flex justify-content-between align-items-center">
                <label class="form-label" for="yogaservice-status">{{ $t('category.lbl_status') }}</label>
                <div class="form-check form-switch">
                  <input class="form-check-input" :value="1" name="status" id="yogaservice-status" type="checkbox" v-model="status" />
                </div>
              </div>
            </div>
            <div class="form-group">
              <div class="d-flex justify-content-between align-items-center">
                <label class="form-label" for="is-group-booking-status">{{ $t('yoga.lbl_is_group_booking') }}</label>
                <div class="form-check form-switch">
                  <input class="form-check-input" :value="1" name="is_group_booking" id="is-group-booking-status" type="checkbox" v-model="is_group_booking" />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <FormFooter :IS_SUBMITED="IS_SUBMITED"></FormFooter>
    </div>
  </form>
</template>
<script setup>
import { onMounted, onUnmounted, ref, watch, computed } from 'vue'
import { INDEX_LIST_URL, EDIT_URL, STORE_URL, UPDATE_URL, YOGA_CENTER_LIST, YOGA_CATEGORY_LIST } from '../constant/yogaservice'
import { useField, useForm } from 'vee-validate'
import { useSelect } from '@/helpers/hooks/useSelect'
import * as yup from 'yup'
import { readFile } from '@/helpers/utilities'
import { useRequest } from '@/helpers/hooks/useCrudOpration'
import { buildMultiSelectObject } from '@/helpers/utilities'

import FormHeader from '@/vue/components/form-elements/FormHeader.vue'
import FormFooter from '@/vue/components/form-elements/FormFooter.vue'
import InputField from '@/vue/components/form-elements/InputField.vue'
import FormElement from '@/helpers/custom-field/FormElement.vue'
import { data } from 'jquery'

// props
const props = defineProps({
  createTitle: { type: String, default: '' },
  editTitle: { type: String, default: '' },
  createNestedTitle: { type: String, default: '' },
  editNestedTitle: { type: String, default: '' },
  defaultImage: { type: String, default: 'https://dummyimage.com/600x300/cfcfcf/000000.png' },
  customefield: { type: Array, default: () => [] },
  categoryId: { type: Number, default: 0 },
  currentId: { type: Number, default: 0 },
  isSubCategory: { type: Boolean, default: false }
})
const CURRENCY_SYMBOL = ref(window.defaultCurrencySymbol)
const { getRequest, storeRequest, updateRequest } = useRequest()

const singleSelectOption = ref({
  closeOnSelect: true,
  searchable: true
})
const multiSelectOption = ref({
  mode: 'tags',
  closeOnSelect: true,
  searchable: true
})
const yogacenter = ref({ options: [], list: [] })

useSelect({ url: YOGA_CENTER_LIST }, { value: 'id', label: 'yogacenter_name' }).then((data) => (yogacenter.value = data))

const yogacategory = ref({ options: [], list: [] })

useSelect({ url: YOGA_CATEGORY_LIST }, { value: 'id', label: 'name' }).then((data) => (yogacategory.value = data))

const category_name = ref(null)
const extra = ref([{ name: '', value: '' }])
const clearExtra = () => {
  extra.value = [{ name: '', value: '' }]
}
function addField() {
  extra.value.push({ name: '', value: '' })
}

function removeField(index) {
  if (extra.value.length > 1) {
    extra.value.splice(index, 1)
  }
}
// Edit Form Or Create Form
const currentId = ref(0)
const updatecurrentId = (e) => {
  setFormData(defaultData())
  currentId.value = Number(e.detail.form_id)
  parent_id.value = e.detail.parent_id || null
  category_name.value = null
  if (props.isSubCategory) {
    getCategories()
  }
}
watch(
  currentId,
  () => {
    if (currentId.value > 0) {
      getRequest({ url: EDIT_URL, id: currentId.value }).then((res) => {
      extra.value = res.data.extra
      if (res.status) {
        setFormData(res.data)
      }
    })
    } else {
      setFormData(defaultData())
      extra.value = [{ name: '', value: '' }];
    }
  },
  { deep: true }
)

onMounted(() => document.addEventListener('crud_change_id', updatecurrentId))
onUnmounted(() => document.removeEventListener('crud_change_id', updatecurrentId))

/*
 * Form Data & Validation & Handeling
 */

// File Upload Function
const ImageViewer = ref(null)
const profileInputRef = ref(null)
const fileUpload = async (e) => {
  let file = e.target.files[0]
  await readFile(file, (fileB64) => {
    ImageViewer.value = fileB64
    profileInputRef.value.value = ''
  })
  file_url.value = file
}

// Function to delete Images
const removeImage = ({ imageViewerBS64, changeFile }) => {
  imageViewerBS64.value = null
  changeFile.value = null
}

const removeLogo = () => removeImage({ imageViewerBS64: ImageViewer, changeFile: file_url })
const fieldsJson = computed(() => JSON.stringify(extra.value))
// Default FORM DATA
const defaultData = () => {
  ImageViewer.value = props.defaultImage
  errorMessages.value = {}
  return {
    name: '',
    description: '',
    yogacenter_id: [],
    category_id: data.category_id ?? null,
    parent_id: props.categoryId ?? null,
    duration: '',
    charges: '',
    capacity: '',
    status: true,
    is_group_booking: true,
    file_url: null,
    custom_fields_data: {},
    extra: {}
  }
}

//  Reset Form
const setFormData = (data) => {
  ImageViewer.value = data.file_url || props.defaultImage
  category_name.value = data.category_name
  resetForm({
    values: {
      name: data.name,
      description: data.description,
      yogacenter_id: data.yogacenter_id,
      category_id: data.category_id,
      parent_id: data.parent_id,
      duration: data.duration,
      capacity: data.capacity,
      charges: data.charges,
      status: data.status ? true : false,
      is_group_booking: data.is_group_booking ? true : false,
      file_url: data.file_url,
      custom_fields_data: data.custom_field_data,
      extra: data.extra || []
    }
  })
}

// Reload Datatable, SnackBar Message, Alert, Offcanvas Close
const errorMessages = ref({})

const reset_datatable_close_offcanvas = (res) => {
  IS_SUBMITED.value = false
  if (res.status) {
    window.successSnackbar(res.message)
    renderedDataTable.ajax.reload(null, false)
    bootstrap.Offcanvas.getInstance('#form-offcanvas').hide()
    setFormData(defaultData())
    removeImage({ imageViewerBS64: ImageViewer, changeFile: file_url })
    clearExtra()
  } else {
    window.errorSnackbar(res.message)
    errorMessages.value = res.all_message
  }
}

const numberRegex = /^\d+$/
// Validations
const validationSchema = yup.object({
  name: yup
    .string()
    .required('Sub Category name is a required field')
    .test('is-string', 'Only strings are allowed', (value) => {
      // Regular expressions to disallow special characters and numbers
      const specialCharsRegex = /[!@#$%^&*(),.?":{}|<>\-_;'\/+=\[\]\\]/
      return !specialCharsRegex.test(value) && !numberRegex.test(value)
    }),
  description: yup.string()
  .required('Description field is required')
  .test('no-script-tags', 'The Description field cannot contain script tags.', function (value) {
    const scriptTagRegex = /<script\b[^>]*>(.*?)/is
    return !scriptTagRegex.test(value)
  }),
  category_id: yup.string().required('Category is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
  charges: yup.number().required('Charges is a required field'),
  duration: yup.number().required('Duration is a required field'),
  capacity: yup.string().required('capacity is a required field'),
  yogacenter_id: yup.array().test('yogacenter_id', 'yoga center is a required field', function (value) {
    if (value.length == 0) {
      return false
    }
    return true
  }),

})

const { handleSubmit, errors, resetForm } = useForm({ validationSchema })

const { value: name } = useField('name')
const { value: description } = useField('description')
const { value: yogacenter_id } = useField('yogacenter_id')
const { value: category_id } = useField('category_id')
const { value: parent_id } = useField('parent_id')
const { value: duration } = useField('duration')
const { value: capacity } = useField('capacity')
const { value: charges } = useField('charges')
const { value: status } = useField('status')
const { value: is_group_booking } = useField('is_group_booking')
const { value: file_url } = useField('file_url')
const { value: custom_fields_data } = useField('custom_fields_data')

// Form Submit
const IS_SUBMITED = ref(false)
const formSubmit = handleSubmit((values) => {
  if (IS_SUBMITED.value) return false
  IS_SUBMITED.value = true
  values.custom_fields_data = JSON.stringify(values.custom_fields_data)
  values.extra = fieldsJson.value
  if (currentId.value > 0) {
    updateRequest({ url: UPDATE_URL, id: currentId.value, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
  } else {
    storeRequest({ url: STORE_URL, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
  }
})
</script>
