<template>
    <!-- Modal -->
        <div class="modal fade" id="exampleModal" tabindex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h1 class="modal-title fs-5" id="exampleModalLabel">{{ $t('yoga.lbl_delete_class') }}</h1>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                    </div>
                    <div class="modal-body">
                        <div class="row" id="form-offcanvas">
                          <div v-if="EventData.length>1" class="mb-2">
                            <button  class="btn btn-danger" @click="DeletAllEvent('Are you certain you want to delete all?')">{{ $t('yoga.delete_all_event') }}</button>
                          </div>
                          <div>
                            <button class="btn btn-danger" @click="DeletEvent('Are you certain you want to delete it?')" >{{ $t('yoga.delete_event') }}</button>
                          </div>
                        </div>
                     </div>
  
                </div>
            </div>
        </div>
</template>
<script setup>
import { ref, onMounted ,watch} from 'vue'
import { useRequest } from '@/helpers/hooks/useCrudOpration'
import { GET_CLASSES_DATA,DELETE_EVENT} from '../../constant/yogaclasses'
import { confirmSwal } from '@/helpers/utilities'

const emit = defineEmits(['deleteData'])

const { getRequest,listingRequest} = useRequest()

const props = defineProps({
    class_event_id: { type: Number, default: 0 }
})

const currentId=ref(props.class_event_id)
const EventData=ref([]);

watch(
  () => props.class_event_id,
  (value) => {
    currentId.value = value
     if(value>0){
       getRequest({ url: GET_CLASSES_DATA, id: value }).then((res) => {
         if(res.status && res.data){
            EventData.value=res.data;
         }
      })
    } 
  }
)

const DeletAllEvent=(message)=>{

  confirmSwal({title: message}).then((result) => {
  if(!result.isConfirmed) return
  listingRequest({ url: DELETE_EVENT, data: { id: currentId.value, type:'all' }}).then((res) => {
    if(res.status) {
      Swal.fire({
        title: 'Deleted',
        text: res.message,
        icon: "success"
      })
      emit('deleteData')
      bootstrap.Modal.getInstance(document.getElementById("exampleModal")).hide()

     }
   })
  })
}


const DeletEvent=(message)=>{
  confirmSwal({title: message}).then((result) => {
  if(!result.isConfirmed) return
  listingRequest({ url: DELETE_EVENT, data: { id: currentId.value, type:'single' }}).then((res) => {
    if(res.status) {
      Swal.fire({
        title: 'Deleted',
        text: res.message,
        icon: "success"
      })

      emit('deleteData')
      bootstrap.Modal.getInstance(document.getElementById("exampleModal")).hide()

     }
   })
  })

}

</script>