onMounted(() => {
  setFormData(defaultData())
  getCountry()
  getVendorList()
  getYogaCenter()
  getAppConfiguration()
})

const IS_SUBMITED = ref(false)
const formSubmit = handleSubmit((values) => {
  if (IS_SUBMITED.value) return false
  values.qualifications = JSON.stringify(userInputList.value)
  values.users = JSON.stringify(values.users)
  let signatureData = null
  if (signature.value) {
    signatureData = signature.value.save('image/jpeg')
  }
  values.signature = signatureData
  if (props.customefield > 0) {
    values.custom_fields_data = JSON.stringify(values.custom_fields_data)
  }

  if (currentId.value > 0) {
    updateRequest({ url: UPDATE_URL, id: currentId.value, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
  } else {
    storeRequest({ url: STORE_URL, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
  }
})

const changeLogo = (e) => fileUpload(e, { imageViewerBS64: ImageViewer, changeFile: profile_image })
const removeLogo = () => removeImage({ imageViewerBS64: ImageViewer, changeFile: profile_image })
