<template>
  <form @submit="formSubmit">
    <div class="offcanvas offcanvas-end" tabindex="-1" id="yoga-class-form-offcanvas" aria-labelledby="form-offcanvasLabel">
      <div class="offcanvas-header border-bottom">
        <h5 class="offcanvas-title" id="form-offcanvasLabel">
          <span>{{ offcanvasTitle }}</span>
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="offcanvas" aria-label="Close"></button>
      </div>

      <div class="offcanvas-body">
        <div class="row">
          <div class="col-md-6">
            <div class="row">
              <InputField :is-required="true" :label="$t('category.lbl_name')" placeholder="" v-model="name" :error-message="errors.name" :error-messages="errorMessages['name']"></InputField>

              <div class="form-group col-md-12">
                <label class="form-label" for="description">{{ $t('category.lbl_description') }} <span class="text-danger">*</span></label>
                <textarea :is-required="true" class="form-control" v-model="description" id="description"></textarea>
                <span v-if="errorMessages['description']">
                  <ul class="text-danger">
                    <li v-for="err in errorMessages['description']" :key="err">{{ err }}</li>
                  </ul>
                </span>
                <span class="text-danger">{{ errors.description }}</span>
              </div>
            </div>
          </div>
          <div class="col-md-6 text-center">
            <img :src="ImageViewer || defaultImage" alt="feature-image" class="img-fluid mb-2 avatar-140 avatar-rounded" />
            <div class="d-flex align-items-center justify-content-center gap-2">
              <input type="file" ref="profileInputRef" class="form-control d-none" id="file_url" name="file_url" @change="fileUpload" accept=".jpeg, .jpg, .png, .gif" />
              <label class="btn btn-info" for="file_url">{{ $t('messages.upload') }}</label>
              <input type="button" class="btn btn-danger" name="remove" :value="$t('messages.remove')" @click="removeLogo()" v-if="ImageViewer" />
            </div>
          </div>

          <div class="row">
            <div class="form-group col-md-4">
              <div class="form-group">
                <label class="form-label" for="yogacenter">{{ $t('yoga.lbl_yoga_center') }} <span class="text-danger">*</span></label>
                <Multiselect id="yoga_center" v-model="yoga_center" :multiple="true" :value="yoga_center" :placeholder="$t('yoga.lbl_yoga_center')" v-bind="singleSelectOption" :options="yogacenter.options" class="form-group" @select="selectCenter"> </Multiselect>
                <span v-if="errorMessages['yoga_center']">
                  <ul class="text-danger">
                    <li v-for="err in errorMessages['yoga_center']" :key="err">{{ err }}</li>
                  </ul>
                </span>
                <span class="text-danger">{{ errors.yoga_center }}</span>
              </div>
            </div>

            <div class="form-group col-md-4">
              <label class="form-label" for="yogacategory">{{ $t('yoga.lbl_yoga_category') }} <span class="text-danger">*</span></label>
              <Multiselect id="category_id" v-model="category_id" :value="category_id" :placeholder="$t('yoga.yogacategory')" v-bind="singleSelectOption" :options="yogacategory.options" class="form-group"> </Multiselect>
              <span v-if="errorMessages['category_id']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['category_id']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.category_id }}</span>
            </div>

            <div class="form-group col-md-4">
              <label class="form-label" for="yogacategory">{{ $t('yoga.lbl_yoga_instructor') }} <span class="text-danger">*</span></label>
              <Multiselect id="instructor_id" v-model="instructor_id" :value="instructor_id" :placeholder="$t('yoga.yoga_instructor')" v-bind="singleSelectOption" :options="InstructorList.options" class="form-group"> </Multiselect>
              <span v-if="errorMessages['instructor_id']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['instructor_id']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.instructor_id }}</span>
            </div>

            <div class="col-md-6 form-group">
              <label class="form-label" for="start_date_time">{{ $t('yoga.lbl_start_date_time') }} <span class="text-danger">*</span></label
              ><br />

              <flat-pickr placeholder="Select Start At" id="start_date_time" class="form-control col-md-6" v-model="start_date_time" :value="start_date_time" :config="start_config"  ></flat-pickr>
              <span v-if="errorMessages['start_date_time']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['start_date_time']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.start_date_time }}</span>
            </div>

            <div class="col-md-6 form-group">
              <label class="form-label" for="end_date_time">{{ $t('yoga.lbl_end_date_time') }} <span class="text-danger">*</span></label
              ><br />

              <flat-pickr placeholder="Select End At" id="end_date_time" class="form-control col-md-6" v-model="end_date_time" :value="end_date_time" :config="end_config"></flat-pickr>
              <span v-if="errorMessages['end_date_time']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['end_date_time']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.end_date_time }}</span>
            </div>

            <InputField class="col-md-6 form-group" :is-required="true" :label="`${$t('yoga.lbl_charges')} (${CURRENCY_SYMBOL})`" placeholder="" v-model="charges" :error-message="errors['charges']" :error-messages="errorMessages['charges']"></InputField>
            <InputField class="col-md-6 form-group" :is-required="true" :label="`${$t('yoga.lbl_capacity')}`" placeholder="" v-model="capacity" :error-message="errors['capacity']" :error-messages="errorMessages['capacity']"></InputField>
         

            <div class="col-md-4">
              <label class="form-label" for="repeat_type">{{ $t('yoga.lbl_repeat_type') }} <span class="text-danger">*</span></label>
              <Multiselect id="repeat_type" v-model="repeat_type" :value="repeat_type" v-bind="repeat_type_data" class="form-group"></Multiselect>
              <span v-if="errorMessages['repeat_type']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['repeat_type']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.repeat_type }}</span>
            </div>

            <div v-if="repeat_type !='does_not_repeat' && repeat_type !=''" class="row">

            <div class="col-md-4">

                <label class="form-label" for="repeat_duration">{{ $t('yoga.repeat_duration') }}  [{{ repeat_type }}]</label>
                <input type="number" class="form-control" v-model="repeat_duration" id="repeat_duration" min="1"/>
                <span v-if="errorMessages['repeat_duration']">
                  <ul class="text-danger">
                    <li v-for="err in errorMessages['repeat_duration']" :key="err">{{ err }}</li>
                  </ul>
                </span>
                <span class="text-danger">{{ errors.repeat_duration }}</span>
            
            </div>

            <div class="col-md-4" >
              <label class="form-label" for="repeat_till_type">{{ $t('yoga.lbl_repeat_till_type') }} </label>
              <Multiselect id="repeat_till_type" v-model="repeat_till_type" :value="repeat_till_type" v-bind="repeat_till_type_data" class="form-group"></Multiselect>
              <span v-if="errorMessages['repeat_till_type']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['repeat_till_type']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.repeat_till_type }}</span>
            </div>


            <div class="col-md-4 form-group" v-if="repeat_till_type=='until_date'">
              <label class="form-label" for="repeat_till_date">{{ $t('yoga.lbl_repeat_till_date') }} </label
              ><br />

              <flat-pickr placeholder="Select Date" id="repeat_till_date" class="form-control col-md-6" v-model="repeat_till_date" :value="repeat_till_date" :config="repeat_config"></flat-pickr>
              <span v-if="errorMessages['repeat_till_date']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['repeat_till_date']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.repeat_till_date }}</span>
            </div>

            <div class="col-md-4" v-if="repeat_till_type=='total_occurnce'">

              <label class="form-label" for="number_of_occurrences">{{ $t('yoga.number_of_occurrences') }} </label>
              <input type="number" class="form-control" v-model="number_of_occurrences" id="number_of_occurrences" />
              <span v-if="errorMessages['number_of_occurrences']">
                <ul class="text-danger">
                  <li v-for="err in errorMessages['number_of_occurrences']" :key="err">{{ err }}</li>
                </ul>
              </span>
              <span class="text-danger">{{ errors.number_of_occurrences }}</span>
          
          </div>

            <div class="form-group mb-2 col-md-12" v-if="repeat_type=='monthly'">
              <div class="d-flex justify-content-between align-items-center">
                <label class="form-label mb-0" for="category-is_repeat_week_day">{{ $t('yoga.is_repeat_week_day') }}</label>
                <div class="form-check form-switch">
                  <input class="form-check-input" :value="0" name="is_repeat_week_day" id="category-is_repeat_week_day" type="checkbox" v-model="is_repeat_week_day" />
                </div>
              </div>
            </div>

            <div class="form-group col-md-12" v-if="repeat_type=='weekly'">
              <label class="form-label" for="days">{{ $t('yoga.repeat_week_days') }}</label>
              <div class="d-flex w-100 gap-3" role="group" aria-label="Basic checkbox toggle button group">
                <template v-for="(item, index) in WEEK_DAYS" :key="index">
                  <div class="d-flex gap-3 form-check">
                    <input type="checkbox" class="form-check-input" :id="`${item}-days`" autocomplete="off" :value="item" v-model="days" />
                    <label class="form-label mb-0" :for="`${item}-days`">{{ item }}</label>
                  </div>
                </template>
              </div>
              <span v-if="errorMessages['days']">
                <span class="text-danger">{{ errorMessages['days'] }}</span>
              </span>
            </div>

          </div>

        </div>


          <div class="form-group mb-0 col-md-12">
            <div class="d-flex justify-content-between align-items-center">
              <label class="form-label mb-0" for="category-status">{{ $t('therapy.lbl_status') }}</label>
              <div class="form-check form-switch">
                <input class="form-check-input" :value="1" name="status" id="category-status" type="checkbox" v-model="status" />
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="form-group mb-0 col-md-12" v-if="eventId>0">

      <button type="button" data-bs-toggle="modal" data-bs-target="#exampleModal"  class="btn btn-primary">{{ $t('messages.delete') }}</button>

      </div>

      <FormFooter :IS_SUBMITED="IS_SUBMITED"></FormFooter>
      <!-- <FormFooter></FormFooter> -->

    </div>

   
  </form>

  <DeleteClassEvent :class_event_id="eventId" @deleteData="updateEventDetails"></DeleteClassEvent>
</template>

<script setup>
import { ref, reactive, watch, onMounted, computed } from 'vue'
import InputField from '@/vue/components/form-elements/InputField.vue'
import FormFooter from '@/vue/components/form-elements/FormFooter.vue'
import { STORE_URL,EDIT_URL, UPDATE_URL, YOGA_CENTER_LIST, YOGA_CATEGORY_LIST, INSTRUCTORS_LIST } from '../constant/yogaclasses'
import { useSelect } from '@/helpers/hooks/useSelect'
import FlatPickr from 'vue-flatpickr-component'
import { readFile } from '@/helpers/utilities'
import { useField, useForm } from 'vee-validate'
import { useRequest } from '@/helpers/hooks/useCrudOpration'
import DeleteClassEvent from '../component/modal/DeleteClassEvent.vue'
import * as yup from 'yup'
import moment from 'moment';

const emit = defineEmits(['onSubmit'])

const props = defineProps({
  defaultImage: { type: String, default: 'http://127.0.0.1:8000/img/default.png' },
  classData: {
    default: () => {
      return {
        id: 0,
        start_date_time: null,
        slot_durations:null,
        
      }
    }
  }
})

const singleSelectOption = ref({
  closeOnSelect: true,
  searchable: true
})

const { getRequest, storeRequest, updateRequest, listingRequest } = useRequest()
const CURRENCY_SYMBOL = ref(window.defaultCurrencySymbol)

const eventId=ref(0);

watch(
  () => props.classData,
  (value) => {

    if(value.id !== null && value.id !== undefined && value.id !== 0) {
      eventId.value = value.id;
      editClassesData(eventId.value);
      
    } else {
      setFormData(defaultData());
    }
    getCenter();
  },
  { deep: true }
);

const editClassesData= (value) =>{

  getRequest({ url: EDIT_URL, id: value }).then((res) => {
      if (res.status) {
        selectCenter(res.data.yoga_center)
        setFormData(res.data)
      }else{
        setFormData(defaultData())
      }
    })

}

const offcanvasTitle = computed(() => {
  return props.classData.id !== 0 ? 'Edit Yoga Class' : 'Create Yoga Class'
})


const yogacenter = ref({ options: [], list: [] })

const getCenter = () => {
  useSelect({ url: YOGA_CENTER_LIST }, { value: 'id', label: 'yogacenter_name' }).then((data) => (yogacenter.value = data))
}

const yogacategory = ref({ options: [], list: [] })
const InstructorList = ref({ options: [], list: [] })

const selectCenter = (value) => {
  category_id.value = ''
  instructor_id.value=''
  useSelect({ url: YOGA_CATEGORY_LIST, data: value }, { value: 'id', label: 'name' }).then((data) => (yogacategory.value = data))
  useSelect({ url: INSTRUCTORS_LIST, data: value }, { value: 'id', label: 'instructor_name' }).then((data) => (InstructorList.value = data))
}

const start_config = ref({
  dateFormat: 'Y-m-d H:i',
  enableTime: true,
  static: true,
  minDate: 'today'
})

const end_config = ref({
  dateFormat: 'Y-m-d H:i',
  enableTime: true,
  static: true,
  minDate: 'today'
})

const repeat_config = ref({
  dateFormat: 'Y-m-d',
  static: true,
  minDate: 'today'
})


const IS_SUBMITED = ref(false)
const ImageViewer = ref(null)
const profileInputRef = ref(null)
const fileUpload = async (e) => {
  let file = e.target.files[0]
  await readFile(file, (fileB64) => {
    ImageViewer.value = fileB64
    profileInputRef.value.value = ''
  })
  file_url.value = file
}

// Function to delete Images
const removeImage = ({ imageViewerBS64, changeFile }) => {
  imageViewerBS64.value = null
  changeFile.value = null
}

const repeat_type_data = ref({
  searchable: true,
  options: [
    { label: 'Does not Repeat', value: 'does_not_repeat' },
    { label: 'Daily', value: 'daily' },
    { label: 'Weekly', value: 'weekly' },
    { label: 'Monthly', value: 'monthly' },
    { label: 'Yearly', value: 'yearly' }, 
  ],
  closeOnSelect: true,
  createOption: true
})

const repeat_till_type_data = ref({
  searchable: true,
  options: [
    { label: 'Forever For 1 Year', value: 'forever' },
    { label: 'Until an End Date', value: 'until_date' },
    { label: 'For a total number of occurrences', value: 'total_occurnce' },
  
  ],
  closeOnSelect: true,
  createOption: true
})

const WEEK_DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

const removeLogo = () => removeImage({ imageViewerBS64: ImageViewer, changeFile: file_url })

const defaultData = () => {
  eventId.value=0
  ImageViewer.value = props.defaultImage

  const startDateFormatted = ref(null);
    const endDateFormatted = ref(null);

  if(props.classData.start_date_time !=null){
     
    const [hours, minutes] = props.classData.slot_durations.split(':').map(Number);
    const slotDurationMinutes = hours * 60 + minutes;

    const startDateTime = moment(props.classData.start_date_time);
    const endDateTime = startDateTime.clone().add(slotDurationMinutes, 'minutes');

    startDateFormatted.value = startDateTime.format('Y-MM-DD HH:mm');
    endDateFormatted.value = endDateTime.format('Y-MM-DD HH:mm');

  }

  errorMessages.value = {}
  return {
    name: '',
    description: '',
    yoga_center: '',
    category_id: '',
    charges: '',
    capacity: '',
    instructor_id: '',
    start_date_time: startDateFormatted.value,
    end_date_time: endDateFormatted.value,
    status: true,
    file_url: null,
    repeat_type:'does_not_repeat',
    repeat_duration:1,
    repeat_till_type:'forever',
    repeat_till_date:'',
    number_of_occurrences:10,
    is_repeat_week_day: 0,
    days:[],
    
  }
}


//  Reset Form
const setFormData = (data) => {
  ImageViewer.value = data.file_url 

  const startDateFormatted = ref(null);
    const endDateFormatted = ref(null);

  if(props.classData.start_date_time !=null){
     
    const [hours, minutes] = props.classData.slot_durations.split(':').map(Number);
    const slotDurationMinutes = hours * 60 + minutes;

    const startDateTime = moment(props.classData.start_date_time);
    const endDateTime = startDateTime.clone().add(slotDurationMinutes, 'minutes');

    startDateFormatted.value = startDateTime.format('Y-MM-DD HH:mm');
    endDateFormatted.value = endDateTime.format('Y-MM-DD HH:mm');

  }

    const startDate = ref(null);
    const EndDate = ref(null);

  if(data.start_date_time !=null && data.end_date_time !=null ){

    const startDate1 = moment(data.start_date_time);
    const endDate1 =moment(data.end_date_time);
     
     startDate.value= startDate1.format('Y-MM-DD HH:mm');
     EndDate.value= endDate1.format('Y-MM-DD HH:mm');

  }
  resetForm({
    values: {
      name: data.name,
      description: data.description,
      yoga_center: data.yoga_center,
      category_id: data.category_id,
      capacity: data.capacity,
      charges: data.charges,
      instructor_id: data.instructor_id,
      start_date_time:startDate.value,
      end_date_time:EndDate.value,
      status: data.status ? true : false,
      file_url: data.file_url,
      repeat_type:data.repeat_type,
      repeat_duration:data.repeat_duration || 1,
      repeat_till_type:data.repeat_till_type || 'forever' ,
      repeat_till_date:data.repeat_till_value,
      number_of_occurrences:data.repeat_till_value || 10,
      is_repeat_week_day:data.is_repeat_week_day,
      days:data.days
    }
  })
}

const numberRegex = /^\d+$/

 const validationSchema = yup.object({
      name: yup.string().required('Name is a required field'),
      description: yup.string().required('Description is a required field'),
      yoga_center: yup.string().required('Yoga Center is a required field'),
      instructor_id: yup.string().required('Yoga Instructor is a required field'),
      capacity: yup.string().required('Capacity is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
      charges: yup.string().required('Charges is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
      start_date_time: yup.string().required('Start Date Time is a required field'),
      end_date_time: yup.string().required('End Date Time is a required field'),
      repeat_type: yup.string().required('Repeat is a required field'),

 })

const { handleSubmit, errors, resetForm } = useForm({
  validationSchema
})
const { value: name } = useField('name')
const { value: description } = useField('description')
const { value: yoga_center } = useField('yoga_center')
const { value: category_id } = useField('category_id')
const { value: instructor_id } = useField('instructor_id')
const { value: capacity } = useField('capacity')
const { value: charges } = useField('charges')
const { value: start_date_time } = useField('start_date_time')
const { value: end_date_time } = useField('end_date_time')
const { value: repeat_type } = useField('repeat_type')
const { value: repeat_duration } = useField('repeat_duration')
const { value: repeat_till_type } = useField('repeat_till_type')
const { value: repeat_till_date } = useField('repeat_till_date')
const { value: number_of_occurrences } = useField('number_of_occurrences')
const { value: is_repeat_week_day } = useField('is_repeat_week_day')
const { value: days } = useField('days')
const { value: status } = useField('status')
const { value: file_url } = useField('file_url')

const errorMessages = ref({})

const formSubmit = handleSubmit((values) =>{

  values.time_slot = props.classData.slot_durations;

     switch (repeat_type.value) {
         case 'daily':
             values.extra_value = null;
             break;
     
         case 'weekly':
             values.extra_value = JSON.stringify(days.value);
             break;
     
         case 'monthly':
             if(is_repeat_week_day ==1){

               is_repeat_week_day.value=1

              }else{

                is_repeat_week_day.value=0
              }
              values.extra_value = JSON.stringify(is_repeat_week_day.value);
              break;
     
         case 'yearly':
             values.extra_value = null;
             break;
     
         default:
             values.repeat_duration = 0;
             values.repeat_till_type = '';
             values.repeat_till_value = '';
             values.extra_value = '';
             break;
     }
     
     if (repeat_till_type.value === 'until_date') {
         values.repeat_till_value = repeat_till_date.value
     }else if(repeat_till_type.value === 'total_occurnce'){
      values.repeat_till_value =number_of_occurrences.value
     }else {
         values.repeat_till_value = ''
     }
     

  if(!IS_SUBMITED.value) {
    IS_SUBMITED.value = true;

    if (props.classData.id >0) {
      updateRequest({ url: UPDATE_URL, id: props.classData.id, body: values, type: 'file' }).then((res) => {
        submiting_booking(res)
      })
    } else {

      storeRequest({ url: STORE_URL, body: values, type: 'file' }).then((res) => {
        submiting_booking(res)
      })
    }
  }
})

const updateEventDetails = () => {
  
      setFormData(defaultData())
      const elem = document.getElementById('yoga-class-form-offcanvas')
      const form = bootstrap.Offcanvas.getOrCreateInstance(elem)
      form.hide()

      emit('onSubmit')
}

const submiting_booking = (res) => {
  IS_SUBMITED.value = false;
  if (res.status) {
    window.successSnackbar(res.message)
   
      setFormData(defaultData())
      const elem = document.getElementById('yoga-class-form-offcanvas')
      const form = bootstrap.Offcanvas.getOrCreateInstance(elem)
      form.hide()
    
     } else {
      window.errorSnackbar(res.message)
  }
  emit('onSubmit')
}
</script>

<style scoped>
@media only screen and (min-width: 768px) {
  .offcanvas {
    width: 80%;
  }
}

@media only screen and (min-width: 1280px) {
  .offcanvas {
    width: 60%;
  }
}

.selected_slot {
  background-color: #3498db;
  color: #fff;
}
</style>
