
export const MODULE = 'yogaclass'
export const INDEX_URL = () => {return {path: `${MODULE}/index_list`, method: 'GET'}}
export const STORE_URL = () => {return {path: `${MODULE}`, method: 'POST'}}
export const UPDATE_URL = (id) => {return {path: `${MODULE}/${id}`, method: 'POST'}}
export const YOGA_CENTER_LIST = () => {return { path: `yogacenter/index_list`, method: 'GET'}}
export const EDIT_URL = (id) => {return {path: `${MODULE}/${id}/edit`, method: 'GET'}}

export const YOGA_CATEGORY_LIST = (id) => {return {path: `yogacategories/index_list?yoga_center=${id}`, method: 'GET'}}
export const INSTRUCTORS_LIST = (id) => {return {path: `yogainstructor/index_list?yoga_center=${id}`, method: 'GET'}}
export const GET_CLASSES_DATA = (id) => {return {path: `${MODULE}/classes_data/${id}`, method: 'GET'}}

export const DELETE_EVENT = ({id,type}) => {return { path: `${MODULE}/delete_event?id=${id}&type=${type}`, method: 'GET',}}
