export const MODULE = 'yogasession'
export const LISTING_URL = (yogacenter_id) => {return {path: `yogasession/index_list?yogacenter_id=${yogacenter_id}`, method: 'GET'}}
export const STORE_URL = () => {return {path: `${MODULE}`, method: 'POST'}}

export const SERVICE_LIST = (id) => {return {path: `yogaservice/index_list?yogacenter_id=${id}`, method: 'GET'}}

export const CENTER_DATA = (id) => {return {path: `yogacenter/${id}/edit`, method: 'GET'}}