___CSS_LOADER_EXPORT___.push([module.id, ".example{margin:0 auto}", "",{"version":3,"sources":["webpack://./Modules/Yoga/Resources/assets/js/component/InstructorFormOffcanvas.vue"],"names":[],"mappings":"AAimBA,SACE,aACF","sourcesContent":["<template>\n  <form @submit=\"formSubmit\">\n    <div class=\"offcanvas offcanvas-end\" tabindex=\"-1\" id=\"form-offcanvas\" aria-labelledby=\"form-offcanvasLabel\">\n      <FormHeader :currentId=\"currentId\" :editTitle=\"editTitle\" :createTitle=\"createTitle\"></FormHeader>\n      <div class=\"offcanvas-body\">\n        <div class=\"row\">\n          <div class=\"col-12 row\">\n            <div class=\"col-12 row\">\n              <div class=\"form-group col-md-6\">\n                <div class=\"text-center\">\n                  <img :src=\"ImageViewer || defaultImage\" alt=\"profile-image\" class=\"img-fluid mb-2 avatar-140 avatar-rounded\"/>\n                  <div class=\"d-flex align-items-center justify-content-center gap-2\">\n                    <input type=\"file\" ref=\"profileInputRef\" class=\"form-control d-none\" id=\"profile_image\" name=\"profile_image\" accept=\".jpeg, .jpg, .png, .gif\" @change=\"changeLogo\" />\n                    <label class=\"btn btn-info\" for=\"profile_image\">{{ $t('messages.upload') }}</label>\n                    <input type=\"button\" class=\"btn btn-danger\" name=\"remove\" :value=\"$t('messages.remove')\" @click=\"removeLogo()\" v-if=\"ImageViewer\" />\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div class=\"col-12 row\">\n              <InputField class=\"col-md-4\" :is-required=\"true\" :label=\"$t('yoga.lbl_first_name')\" placeholder=\"\" v-model=\"first_name\" :error-message=\"errors.first_name\" :error-messages=\"errorMessages['first_name']\"></InputField>\n              <InputField class=\"col-md-4\" :is-required=\"true\" :label=\"$t('yoga.lbl_last_name')\" placeholder=\"\" v-model=\"last_name\" :error-message=\"errors.last_name\" :error-messages=\"errorMessages['last_name']\"></InputField>\n              <InputField class=\"col-md-4\" :is-required=\"true\" :label=\"$t('yoga.lbl_user_name')\" placeholder=\"\" v-model=\"username\" :error-message=\"errors.username\" :error-messages=\"errorMessages['username']\"></InputField>\n              <InputField class=\"col-md-4\" :is-required=\"true\" :label=\"$t('yoga.lbl_email')\" placeholder=\"\" v-model=\"email\" :error-message=\"errors.email\" :error-messages=\"errorMessages['email']\"></InputField>\n              <div class=\"col-md-4\">\n                <label class=\"form-label\"> {{ $t('yoga.lbl_mobile') }} <span class=\"text-danger\">*</span> </label>\n                <vue-tel-input type=\"number\" :value=\"mobile\" @input=\"handleInput\" v-bind=\"{ mode: 'international', maxLen: 15 }\"></vue-tel-input>\n                <span class=\"text-danger\">{{ errors['mobile'] }}</span>\n              </div>\n\n              <div class=\"col-md-4 form-group\">\n                <label class=\"form-label\">{{ $t('yoga.lbl_gender') }}</label>\n                <div class=\"btn-group w-100\" role=\"group\" aria-label=\"Basic example\">\n                  <template v-for=\"(item, index) in GENDER_OPTIONS\" :key=\"index\">\n                    <input type=\"radio\" class=\"btn-check\" name=\"gender\" :id=\"`${item.id}-for`\" :value=\"item.id\" autocomplete=\"off\" v-model=\"gender\" :checked=\"gender == item.id\" />\n                    <label class=\"btn btn-outline-primary\" :for=\"`${item.id}-for`\">{{ item.text }}</label>\n                  </template>\n                </div>\n              </div>\n              <div class=\"row m-0 p-0\" v-if=\"currentId === 0\">\n              <InputField type=\"password\" class=\"col-md-4\" :is-required=\"true\" :label=\"$t('therapy.lbl_password')\"\n                placeholder=\"\" v-model=\"password\" :error-message=\"errors['password']\"\n                :error-messages=\"errorMessages['password']\"></InputField>\n\n              <InputField type=\"password\" class=\"col-md-4\" :is-required=\"true\" :label=\"$t('therapy.lbl_confirm_password')\"\n                placeholder=\"\" v-model=\"confirm_password\" :error-message=\"errors['confirm_password']\"\n                :error-messages=\"errorMessages['confirm_password']\"></InputField>\n            </div>\n\n              <div class=\"col-md-4 form-group\">\n                <label class=\"form-label\">{{ $t('yoga.lbl_country') }}</label>\n                <Multiselect id=\"country-list\" v-model=\"country\" :value=\"country\" v-bind=\"singleSelectOption\" :options=\"countries.options\" @select=\"getState\" class=\"form-group\"></Multiselect>\n                <span v-if=\"errorMessages['country']\">\n                  <ul class=\"text-danger\">\n                    <li v-for=\"err in errorMessages['country']\" :key=\"err\">{{ err }}</li>\n                  </ul>\n                </span>\n                <span class=\"text-danger\">{{ errors['country'] }}</span>\n              </div>\n              <div class=\"col-md-4 form-group\">\n                <label class=\"form-label\">{{ $t('yoga.lbl_state') }}</label>\n                <Multiselect id=\"state-list\" v-model=\"state\" :value=\"state\" v-bind=\"singleSelectOption\" :options=\"states.options\" @select=\"getCity\" class=\"form-group\"></Multiselect>\n                <span v-if=\"errorMessages['state']\">\n                  <ul class=\"text-danger\">\n                    <li v-for=\"err in errorMessages['state']\" :key=\"err\">{{ err }}</li>\n                  </ul>\n                </span>\n                <span class=\"text-danger\">{{ errors['state'] }}</span>\n              </div>\n              <div class=\"col-md-4 form-group\">\n                <label class=\"form-label\">{{ $t('yoga.lbl_city') }}</label>\n                <Multiselect id=\"city-list\" v-model=\"city\" :value=\"city\" v-bind=\"singleSelectOption\" :options=\"cities.options\" class=\"form-group\"></Multiselect>\n                <span v-if=\"errorMessages['city']\">\n                  <ul class=\"text-danger\">\n                    <li v-for=\"err in errorMessages['city']\" :key=\"err\">{{ err }}</li>\n                  </ul>\n                </span>\n                <span class=\"text-danger\">{{ errors['city'] }}</span>\n              </div>\n              <InputField class=\"col-md-4\" type=\"number\" :is-required=\"true\" :label=\"$t('yoga.lbl_postal_code')\" placeholder=\"\" v-model=\"pincode\" :error-message=\"errors['pincode']\" :error-messages=\"errorMessages['pincode']\"></InputField>\n              <InputField class=\"col-md-4\" :is-required=\"false\" :label=\"$t('yoga.lbl_lat')\" placeholder=\"\" v-model=\"latitude\" :error-message=\"errors['latitude']\" :error-messages=\"errorMessages['latitude']\"></InputField>\n              <InputField class=\"col-md-4\" :is-required=\"false\" :label=\"$t('yoga.lbl_long')\" placeholder=\"\" v-model=\"longitude\" :error-message=\"errors['longitude']\" :error-messages=\"errorMessages['longitude']\"></InputField>\n            </div>\n            <div class=\"form-group col-md-4\">\n              <label class=\"form-label\" for=\"name\">{{ $t('yoga.lbl_date_of_birth') }}</label>\n              <flat-pickr v-model=\"date_of_birth\" class=\"form-control\" />\n            </div>\n            <div class=\"form-group col-md-4\" v-if=\"enable_multi_vendor && (role() === 'admin' || role() === 'demo_admin')\">\n              <label class=\"form-label\" for=\"vendor_id\">{{ $t('sidebar.vendors') }} <span class=\"text-danger\">*</span> </label>\n              <Multiselect class=\"form-group\" v-model=\"vendor_id\" :value=\"vendor_id\" :options=\"vendors.options\"  v-bind=\"singleSelectOption\" @select=\"getYogaCenter\" placeholder=\"Select Vendor\" id=\"vendor_id\"></Multiselect>\n              <span v-if=\"errorMessages['vendor_id']\">\n                <ul class=\"text-danger\">\n                  <li v-for=\"err in errorMessages['vendor_id']\" :key=\"err\">{{ err }}</li>\n                </ul>\n              </span>\n              <span class=\"text-danger\">{{ errors.vendor_id }}</span>\n            </div>\n            <div class=\"form-group col-md-4\">\n              <div class=\"form-group\">\n                <label class=\"form-label\" for=\"yogacenter\">{{ $t('yoga.lbl_yoga_center') }} <span class=\"text-danger\">*</span></label>\n                <Multiselect id=\"yogacenter_id\" v-model=\"yogacenter_id\" :value=\"yogacenter_id\"  :multiple=\"true\"  :placeholder=\"$t('yoga.lbl_yoga_center')\" v-bind=\"multiSelectOption\" :options=\"yogacenter.options\" class=\"form-group\"> </Multiselect>\n                <span v-if=\"errorMessages['yogacenter_id']\">\n                  <ul class=\"text-danger\">\n                    <li v-for=\"err in errorMessages['yogacenter_id']\" :key=\"err\">{{ err }}</li>\n                  </ul>\n                </span>\n                <span class=\"text-danger\">{{ errors.yogacenter_id }}</span>\n              </div>\n            </div>\n            <!-- <div class=\"form-group col-md-4\">\n              <div class=\"form-group\">\n                <label class=\"form-label\" for=\"yogaservice\">{{ $t('yoga.lbl_yoga_service') }} <span class=\"text-danger\">*</span></label>\n                <Multiselect id=\"yogaservice_id\" v-model=\"yogaservice_id\" :multiple=\"true\" :value=\"yogaservice_id\" :placeholder=\"$t('yoga.lbl_yoga_service')\" v-bind=\"multiSelectOption\" :options=\"yogaservice.options\" class=\"form-group\"> </Multiselect>\n                <span v-if=\"errorMessages['yogaservice_id']\">\n                  <ul class=\"text-danger\">\n                    <li v-for=\"err in errorMessages['yogaservice_id']\" :key=\"err\">{{ err }}</li>\n                  </ul>\n                </span>\n                <span class=\"text-danger\">{{ errors.yogaservice_id }}</span>\n              </div>\n            </div> -->\n            <!-- qualification detail-->\n            <legend>{{ $t('therapy.qualification') }}</legend>\n            <div class=\"row\">\n              <div class=\"col-md-12\" v-for=\"(input, index) in userInputList\" :key=\"index\">\n                <div class=\"row\">\n                  <div class=\"form-group col-md-4\">\n                    <label class=\"form-label\" for=\"degree\">{{ $t('therapy.degree') }}</label>\n                    <input type=\"text\" class=\"form-control\" :placeholder=\"$t('therapy.degree')\" v-model=\"input.degree\" id=\"degree\" />\n                    <span class=\"text-danger degree_err\" :id=\"`degree_err_${index}`\"></span>\n                  </div>\n\n                  <div class=\"form-group col-md-4\">\n                    <label class=\"form-label\" for=\"university\">{{ $t('therapy.university') }}</label>\n                    <input type=\"text\" class=\"form-control\" :placeholder=\"$t('therapy.university')\" v-model=\"input.university\" id=\"university\" />\n                    <span class=\"text-danger university_err\" :id=\"`university_err_${index}`\"></span>\n                  </div>\n\n                  <div class=\"form-group col-md-4\">\n                    <label class=\"form-label\" for=\"year\">{{ $t('therapy.year') }}</label>\n                    <flat-pickr v-model=\"input.year\" :config=\"config\" class=\"form-control\" />\n                    <span class=\"text-danger year_err\" :id=\"`year_err_${index}`\"></span>\n                  </div>\n\n                  <div class=\"row\" v-if=\"userInputList.length > 1\">\n                    <div class=\"form-group col-12 text-end\">\n                      <button type=\"button\" @click=\"removeQualification(index)\" class=\"btn btn-danger px-3\"><i class=\"fa-regular fa-trash-can\"></i></button>\n                    </div>\n                    <div class=\"col-12\">\n                      <div class=\"border-top mt-3 pb-5\"></div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n\n              <div class=\"form-group col-md-12 text-end\">\n                <a @click=\"addQualification\" class=\"btn btn-primary\"> <i class=\"fa-solid fa-plus\"></i> {{ $t('therapy.add_qualification') }} </a>\n              </div>\n            </div>\n\n            <InputField class=\"col-md-6\" :is-required=\"false\" :label=\"$t('yoga.lbl_specialization')\" placeholder=\"\" v-model=\"specialization\" :error-message=\"errors['specialization']\" :error-messages=\"errorMessages['specialization']\"></InputField>\n            <InputField class=\"col-md-6\" :is-required=\"false\" :label=\"$t('yoga.lbl_experience')\" placeholder=\"\" v-model=\"experience\" :error-message=\"errors['experience']\" :error-messages=\"errorMessages['experience']\"></InputField>\n            <div class=\"form-group col-md-6\">\n              <label class=\"form-label\" for=\"bio\">{{ $t('yoga.lbl_bio') }}</label>\n              <textarea class=\"form-control\" v-model=\"bio\" id=\"bio\"></textarea>\n              <span v-if=\"errorMessages['bio']\">\n                <ul class=\"text-danger\">\n                  <li v-for=\"err in errorMessages['bio']\" :key=\"err\">{{ err }}</li>\n                </ul>\n              </span>\n              <span class=\"text-danger\">{{ errors.bio }}</span>\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label\" for=\"name\">{{ $t('yoga.lbl_signature') }}</label>\n              <Vue3Signature ref=\"signature\" :w=\"'300px'\" :h=\"'50px'\" style=\"border: 1px solid #8a92a6\" class=\"example\"></Vue3Signature>\n              <button @click=\"clear\">Clear</button>\n            </div>\n            <div class=\"form-group col-md-6\">\n              <label class=\"form-label\" for=\"address\">{{ $t('yoga.lbl_address') }} <span class=\"text-danger\">*</span></label>\n              <textarea class=\"form-control\" v-model=\"address\" id=\"address\"></textarea>\n              <span v-if=\"errorMessages['address']\">\n                <ul class=\"text-danger\">\n                  <li v-for=\"err in errorMessages['address']\" :key=\"err\">{{ err }}</li>\n                </ul>\n              </span>\n              <span class=\"text-danger\">{{ errors.address }}</span>\n            </div>\n\n            <div class=\"form-group col-md-6\">\n              <label class=\"form-label\" for=\"description\">{{ $t('yoga.lbl_description') }}</label>\n              <textarea class=\"form-control\" v-model=\"description\" id=\"description\"></textarea>\n              <span v-if=\"errorMessages['description']\">\n                <ul class=\"text-danger\">\n                  <li v-for=\"err in errorMessages['description']\" :key=\"err\">{{ err }}</li>\n                </ul>\n              </span>\n              <span class=\"text-danger\">{{ errors.description }}</span>\n            </div>\n            <div class=\"form-group col-md-2\">\n              <div class=\"d-flex gap-3\">\n                <label class=\"form-label\" for=\"is-manager-status\">{{ $t('yoga.lbl_is_manager') }}</label>\n                <div class=\"form-check form-switch\">\n                  <input class=\"form-check-input\" :value=\"is_manager\" :checked=\"is_manager\" name=\"is_manager\" id=\"is-manager-status\" type=\"checkbox\" v-model=\"is_manager\" />\n                </div>\n              </div>\n            </div>\n\n            <div class=\"form-group col-md-2\">\n              <div class=\"d-flex gap-3\">\n                <label class=\"form-label\" for=\"category-status\">{{ $t('yoga.lbl_status') }}</label>\n                <div class=\"form-check form-switch\">\n                  <input class=\"form-check-input\" :value=\"status\" :checked=\"status\" name=\"status\" id=\"category-status\" type=\"checkbox\" v-model=\"status\" />\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <FormFooter :IS_SUBMITED=\"IS_SUBMITED\"></FormFooter>\n    </div>\n  </form>\n</template>\n\n<script setup>\nimport { ref, onMounted, watch, reactive, computed } from 'vue'\nimport VueSignature from 'vue-signature'\nimport Vue3Signature from 'vue3-signature'\nimport flatPickr from 'vue-flatpickr-component'\nimport 'flatpickr/dist/flatpickr.css'\nimport { useField, useForm } from 'vee-validate'\nimport { EDIT_URL, STORE_URL, UPDATE_URL, YOGA_CENTER_LIST, YOGA_SERVICE_LIST, COUNTRY_URL, STATE_URL, CITY_URL,VENDOR_LIST,APP_CONFIGURATION } from '../constant/yogainstructor'\nimport InputField from '@/vue/components/form-elements/InputField.vue'\nimport { useModuleId, useRequest } from '@/helpers/hooks/useCrudOpration'\nimport { readFile } from '@/helpers/utilities'\nimport { VueTelInput } from 'vue3-tel-input'\nimport { useSelect } from '@/helpers/hooks/useSelect'\nimport * as yup from 'yup'\nimport FormHeader from '@/vue/components/form-elements/FormHeader.vue'\nimport FormFooter from '@/vue/components/form-elements/FormFooter.vue'\n\n// props\nconst props = defineProps({\n  createTitle: { type: String, default: '' },\n  editTitle: { type: String, default: '' },\n  customefield: { type: Array, default: () => [] },\n  defaultImage: { type: String, default: 'https://dummyimage.com/600x300/cfcfcf/000000.png' }\n})\nconst role = () => {\n    return window.auth_role[0];\n}\nconst enable_multi_vendor = ref(false);\nconst getAppConfiguration = (() => {\n  getRequest({ url: APP_CONFIGURATION }).then((res) => {\n    if (res.status && res.enable_multi_vendor === 1) {\n      enable_multi_vendor.value = true;\n    } else {\n      console.error('Error fetching configuration:');\n    }})\n})\nconst ImageViewer = ref(null)\nconst profileInputRef = ref(null)\n\nconst fileUpload = async (e, { imageViewerBS64, changeFile }) => {\n  let file = e.target.files[0]\n  await readFile(file, (fileB64) => {\n    imageViewerBS64.value = fileB64\n\n    profileInputRef.value.value = '';\n  })\n  changeFile.value = file\n}\nconst userInputList = ref([\n  {\n    degree: '',\n    university: '',\n    year: ''\n  }\n])\n\nconst isAddQualificationBtnDisabled = computed(() => {\n  return userInputList.value.some((input) => !input.degree || !input.university || !input.year)\n})\n\nconst addQualification = () => {\n  const newIndex = userInputList.value.length\n  if (!isAddQualificationBtnDisabled.value) {\n    userInputList.value.push({\n      index: newIndex,\n      degree: '',\n      university: '',\n      year: ''\n    })\n\n    const degreeErr = document.querySelector(`#degree_err_${newIndex - 1}`)\n    const universityErr = document.querySelector(`#university_err_${newIndex - 1}`)\n    const yearErr = document.querySelector(`#year_err_${newIndex - 1}`)\n\n    if (degreeErr) degreeErr.textContent = ''\n    if (universityErr) universityErr.textContent = ''\n    if (yearErr) yearErr.textContent = ''\n  } else {\n    const degreeErr = 'Degree is required'\n    const universityErr = 'University is required'\n    const yearErr = 'Year is required'\n    document.querySelector(`#degree_err_${newIndex - 1}`).textContent = degreeErr\n    document.querySelector(`#university_err_${newIndex - 1}`).textContent = universityErr\n    document.querySelector(`#year_err_${newIndex - 1}`).textContent = yearErr\n  }\n}\n\nconst removeQualification = (index) => {\n  userInputList.value.splice(index, 1)\n}\nconst signature = ref(null)\nconst clear = () => {\n  signature.value.clear()\n}\n// Function to delete Images\nconst removeImage = ({ imageViewerBS64, changeFile }) => {\n  imageViewerBS64.value = null\n  changeFile.value = null\n}\n\nconst { getRequest, storeRequest, updateRequest, listingRequest } = useRequest()\n\nconst singleSelectOption = ref({\n  closeOnSelect: true,\n  searchable: true\n})\nconst multiSelectOption = ref({\n  mode: 'tags',\n  closeOnSelect: true,\n  searchable: true\n})\nconst config = ref({\n  dateFormat: 'Y-m-d',\n  static: true,\n  maxDate: 'today'\n})\nconst handleInput = (phone, phoneObject) => {\n  // Handle the input event\n  if (phoneObject?.formatted) {\n    mobile.value = phoneObject.formatted\n  }\n}\nlet selectedCenter = ref([]);\n// Edit Form Or Create Form\nconst currentId = useModuleId(() => {\n  if (currentId.value > 0) {\n    getRequest({ url: EDIT_URL, id: currentId.value }).then((res) => {\n      if (res.data.signature) {\n        signature.value.fromDataURL(res.data.signature)\n      }\n      userInputList.value = res.data.qualification\n      if (res.status && res.data) {\n        setFormData(res.data)\n        getState(country.value)\n        getCity(state.value)\n        selectedCenter.value = res.data.yogacenter_id || [];\n        yogacenter_id.value = selectedCenter.value;\n      }\n    })\n  } else {\n    setFormData(defaultData())\n  }\n})\nconst fieldsJson = computed(() => JSON.stringify(qualification.value))\n\n// Default FORM DATA\nconst defaultData = () => {\n  userInputList.value = [{ degree: '', university: '', year: '' }]\n  ImageViewer.value = props.defaultImage\n  errorMessages.value = {}\n  return {\n\n      first_name: '',\n      last_name: '',\n      username: '',\n      email: '',\n      gender: '',\n      mobile: '',\n      date_of_birth: '',\n      address: '',\n      password: '',\n      confirm_password: '',\n      is_manager: 1,\n      status: 1,\n      vendor_id: '',\n    yogacenter_id: [],\n    // yogaservice_id: [],\n    specialization: '',\n    experience: '',\n    bio: '',\n    signature: '',\n    description: '',\n    profile_image: null,\n    city: '',\n    country: '',\n    pincode: '',\n    state: '',\n    latitude: '',\n    longitude: '',\n    status: 1\n  }\n}\nconst GENDER_OPTIONS = reactive([\n  { id: 'male', text: 'Male' },\n  { id: 'female', text: 'Female' },\n  { id: 'unisex', text: 'Unisex' }\n  // Add more options as needed\n])\nconst vendors = ref({ options: [], list: [] })\nconst getVendorList = () => {\n  useSelect({ url: VENDOR_LIST,data: { system_service: 'yoga' }  }, { value: 'id', label: 'name' }).then((data) => (vendors.value = data))\n  }\nconst yogacenter = ref({ options: [], list: [] })\nconst getYogaCenter = (value) => {\n  yogacenter_id.value = [];\n  useSelect({ url: YOGA_CENTER_LIST,data: { id: value } }, { value: 'id', label: 'yogacenter_name' }).then((data) => (yogacenter.value = data))\n}\n\nconst yogaservice = ref({ options: [], list: [] })\n\nuseSelect({ url: YOGA_SERVICE_LIST }, { value: 'id', label: 'name' }).then((data) => (yogaservice.value = data))\n\nconst countries = ref({ options: [], list: [] })\n\nconst getCountry = () => {\n  useSelect({ url: COUNTRY_URL }, { value: 'id', label: 'name' }).then((data) => (countries.value = data))\n}\n\nconst states = ref({ options: [], list: [] })\n\nconst getState = (value) => {\n  useSelect({ url: STATE_URL, data: value }, { value: 'id', label: 'name' }).then((data) => (states.value = data))\n}\n\nconst cities = ref({ options: [], list: [] })\n\nconst getCity = (value) => {\n  useSelect({ url: CITY_URL, data: value }, { value: 'id', label: 'name' }).then((data) => (cities.value = data))\n}\n\n//  Reset Form\nconst setFormData = (data) => {\n  ImageViewer.value = data.profile_image \n  resetForm({\n    values: {\n\n        first_name: data.first_name,\n        email: data.email,\n        last_name: data.last_name,\n        username: data.username,\n        gender: data.gender,\n        mobile: data.mobile,\n        date_of_birth: data.date_of_birth,\n        address: data.address,\n        is_manager: data.is_manager,\n        status: data.status,\n        password: data.password,\n        confirm_password: data.confirm_password,\n      // yogaservice_id: data.yogaservice_id  || [],\n      vendor_id: data.vendor_id,\n      yogacenter_id: data.yogacenter_id ,\n      specialization: data.specialization,\n      experience: data.experience,\n      bio: data.bio,\n      signature: data.signature,\n      qualification: data.qualification || [],\n      description: data.description,\n      profile_image: data.profile_image,\n      city: data.city,\n      state: data.state,\n      country: data.country,\n      pincode: data.pincode,\n      latitude: data.latitude,\n      longitude: data.longitude,\n      status: data.status\n    }\n  })\n}\n\nconst reset_datatable_close_offcanvas = (res) => {\n  IS_SUBMITED.value = false\n  if (res.status) {\n    window.successSnackbar(res.message)\n    renderedDataTable.ajax.reload(null, false)\n    bootstrap.Offcanvas.getInstance('#form-offcanvas').hide()\n    setFormData(defaultData())\n    removeImage({ imageViewerBS64: ImageViewer, changeFile: profile_image })\n  } else {\n    window.errorSnackbar(res.message)\n    errorMessages.value = res.all_message\n  }\n}\n\n// Validations\nconst validationSchema = yup.object({\n\n    first_name: yup.string().required('First Name is required'),\n    last_name: yup.string().required('Last Name is required'),\n    username: yup.string().required('UserName is required'),\n    email: yup.string().required('Email is required'),\n    mobile: yup.string().required('Contact number is required').matches(/^(\\+?\\d+)?(\\s?\\d+)*$/, 'Phone Number must contain only digits'),\n    address: yup.string().required('Address is required'),\n    password : yup.string().test('password','Password is required' , function(value) {\n      if(currentId === 0 && !value){\n        return false;\n      }\n      return true\n    }\n    ).min(8, 'Password must be at least 8 characters long'),\n    confirm_password : yup.string().test('confirm_password', 'Current password is required', function(value) {\n      if(currentId === 0 && !value){\n        return false;\n      }\n      return true\n    }\n    ).oneOf([yup.ref('password')], 'Passwords must match'),\n\n  pincode: yup.string().required('Pincode is required'),\n  yogacenter_id: yup.array().test('clinic_id', 'Clinic Center is a required field', function (value) {\n        if (value.length == 0) {\n          return false\n        }\n        retu