<template>
    <form @submit.prevent="formSubmit">
      <div class="offcanvas offcanvas-end" tabindex="-1" id="service-instructor-assign-form" aria-labelledby="form-offcanvasLabel">
        <div class="offcanvas-header border-bottom" v-if="service">
          <h6 class="m-0 h5">
            Service: <span>{{ service.name }}</span>
          </h6>
        </div>
  
        <div class="offcanvas-body">
          <div class="form-group">
            <div class="d-grid">
              <div class="d-flex flex-column">
                <div class="form-group">
                  <Multiselect v-model="assign_ids" placeholder="Select Instructor" :canClear="false" :value="assign_ids" v-bind="instructors" @select="selectInstructor" @deselect="removeInstructor" id="instructors_ids">
                    <template v-slot:multiplelabel="{ values }">
                      <div class="multiselect-multiple-label">Select Instructor</div>
                    </template>
                  </Multiselect>
                </div>
              </div>
              <div class="list-group list-group-flush">
                <div v-for="(item, index) in selectedINSTRUCTOR" :key="item" class="list-group-item">
                  <div class="d-flex justify-between align-items-center flex-grow-1 gap-2 mt-2">
                    <span>{{ ++index }} - </span>
                    <div class="d-flex justify-between flex-grow-1 gap-2 my-2">
                    <img :src="item.avatar" class="avatar avatar-40 img-fluid rounded-pill" alt="user" />
                    <div class="flex-grow-1 mt-2"> {{ item.instructor_name }}</div>
                  </div>
                    <button type="button" @click="removeInstructor(item.instructor_id)" class="btn btn-sm text-danger"><i class="fa-regular fa-trash-can"></i></button>
                  </div>
                  <div class="row mb-2">
                  
                    <div class="d-flex justify-content-end align-items-center gap-2 col-6">{{ CURRENCY_SYMBOL }}<input type="number" v-model="item.charges" class="form-control" /></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
  
        <div class="offcanvas-footer">
          <p class="text-center mb-0"><small>Assign Service To Instructor</small></p>
          <div class="d-grid gap-3 p-3">
            <button class="btn btn-primary d-block">
              <i class="fa-solid fa-floppy-disk"></i>
              Update
            </button>
            <button class="btn btn-outline-primary d-block" type="button" data-bs-dismiss="offcanvas">
              <i class="fa-solid fa-angles-left"></i>
              Close
            </button>
          </div>
        </div>
      </div>
    </form>
  </template>
  <script setup>
  import { ref, onMounted } from 'vue'
  import { GET_INSTRUCTOR_ASSIGN_URL, POST_INSTRUCTOR_ASSIGN_URL, EDIT_URL } from '../../constant/yogaservice'
  import { INSTRUCTOR_LIST } from '../../constant/yogaservice'
  import { useModuleId, useRequest } from '@/helpers/hooks/useCrudOpration'
  import { buildMultiSelectObject } from '@/helpers/utilities'
  
  // Request
  const { listingRequest, getRequest, updateRequest } = useRequest()
  
  // Vue Form Select START
  // Select Option
  const instructors = ref({
    mode: 'multiple',
    searchable: true,
    options: []
  })
  const CURRENCY_SYMBOL = ref(window.defaultCurrencySymbol)
  const selectedINSTRUCTOR = ref([])
  // Vue Form Select END
  
  // Form Values
  const assign_ids = ref([])
  const service = ref(null)
  const serviceId = useModuleId(() => {
    getRequest({ url: GET_INSTRUCTOR_ASSIGN_URL, id: serviceId.value }).then((res) => {
      if (res.status && res.data) {
        selectedINSTRUCTOR.value = res.data
        assign_ids.value = res.data.map((item) => item.instructor_id)
      }
    })
    getRequest({ url: EDIT_URL, id: serviceId.value }).then((res) => res.status && (service.value = res.data))
  }, 'instructor_assign')
  
  const instructorList = ref([])
  onMounted(() => {
    listingRequest({ url: INSTRUCTOR_LIST }).then((res) => {
      instructorList.value = res
      instructors.value.options = buildMultiSelectObject(res, { value: 'instructor_id', label: 'instructor_name' })
    })
  })
  
  // Reload Datatable, SnackBar Message, Alert, Offcanvas Close
  const errorMessages = ref([])
  const reset_close_offcanvas = (res) => {
    if (res.status) {
      window.successSnackbar(res.message)
      bootstrap.Offcanvas.getInstance('#service-instructor-assign-form').hide()
      renderedDataTable.ajax.reload(null, false)
    } else {
      window.errorSnackbar(res.message)
      errorMessages.value = res.all_message
    }
  }
  
  const formSubmit = () => {
    const data = { instructors: [] }
    for (let index = 0; index < selectedINSTRUCTOR.value.length; index++) {
      const element = selectedINSTRUCTOR.value[index]
      data.instructors.push({
        instructor_name: element.instructor_name,
        instructor_id: element.instructor_id,
        service_id: element.service_id,
        charges: element.charges,
  
      })
    }
    updateRequest({ url: POST_INSTRUCTOR_ASSIGN_URL, id: serviceId.value, body: data }).then((res) => reset_close_offcanvas(res))
  }
  
  const selectInstructor = (value) => {
    const instructor = instructorList.value.find((instructor) => instructor.instructor_id === value)
    console.log(service.value);
    const newInstructor = {
        instructor_name: instructor.instructor_name,
        instructor_id: instructor.instructor_id,
        service_id: service.value.id,
        avatar:instructor.avatar,
        charges: service.value.charges,
    }
    selectedINSTRUCTOR.value = [...selectedINSTRUCTOR.value, newInstructor]
  }
  
  const removeInstructor = (value) => {
    selectedINSTRUCTOR.value = [...selectedINSTRUCTOR.value.filter((instructor) => instructor.instructor_id !== value)]
    assign_ids.value = [...assign_ids.value.filter((id) => id !== value)]
  }
  </script>
  